 "<div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#3bb3c3;margin-right:.45em\"></span>Eólica 24 %</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#f3c623;margin-right:.45em\"></span>Solar 20 %</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#3f6497;margin-right:.45em\"></span>Hidráulica 10 %</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#4caf7d;margin-right:.45em\"></span>Otras 2 %</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#5b6660;margin-right:.45em\"></span>No renov. 44 %</div>": "<div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#3bb3c3;margin-right:.45em\"></span>Eolikoa % 24</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#f3c623;margin-right:.45em\"></span>Eguzkikoa % 20</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#3f6497;margin-right:.45em\"></span>Hidraulikoa % 10</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#4caf7d;margin-right:.45em\"></span>Besteak % 2</div><div><span style=\"display:inline-block;width:.8em;height:.8em;border-radius:.2em;background:#5b6660;margin-right:.45em\"></span>Ez-berriz. % 44</div>",
